function parseTagIds(value) {
  if (!value) {
    return [];
  }

  if (Array.isArray(value)) {
    return value.map((id) => String(id).trim()).filter(Boolean);
  }

  return String(value)
    .split(',')
    .map((id) => id.trim())
    .filter(Boolean);
}

function resolveRequestedTagIds(config) {
  const baseIds = parseTagIds(config.requestedTagIds);
  const additionalIds = parseTagIds(process.env.TRANSLATIONS_ADDITIONAL_TAG_IDS);

  return [...new Set([...baseIds, ...additionalIds])];
}

function resolveRequestedTagIdsBreakdown(config) {
  const mfeTagIds = parseTagIds(config.requestedTagIds);
  const additionalTagIds = parseTagIds(process.env.TRANSLATIONS_ADDITIONAL_TAG_IDS);

  return {
    mfeTagIds,
    additionalTagIds,
    mergedTagIds: [...new Set([...mfeTagIds, ...additionalTagIds])],
  };
}

module.exports = { resolveRequestedTagIds, resolveRequestedTagIdsBreakdown, parseTagIds };
